// Generated by Claude

import React from 'react';
import { render, screen, fireEvent, waitFor, act } from '@testing-library/react';
import UserNavBar from '@/components/HeaderDropdown';
import * as auth from '@/services/auth';
import * as HeaderDropdown from '@/components/HeaderDropdown';      

jest.mock('next/navigation', () => ({
  usePathname: jest.fn(() => '/sites'),
  useRouter: jest.fn(() => ({ push: jest.fn() })),
}));

jest.mock('@/services/auth', () => ({
  logout: jest.fn(),
}));

jest.mock('@/utils/supabase/client', () => ({
  createClient: jest.fn(() => ({
    auth: {
      getSession: jest.fn().mockResolvedValue({
        data: {
          session: {
            user: {
              email: 'test@example.com',
              app_metadata: { role: 'steward' },
              user_metadata: { full_name: 'Test User', avatar_url: '' },
            },
          },
        },
      }),
    },
  })),
}));

describe('UserNavBar - logout button', () => {
  let navigateSpy: jest.SpyInstance;

  beforeEach(() => {
    jest.clearAllMocks();
    navigateSpy = jest.spyOn(HeaderDropdown, 'navigate').mockImplementation(() => {});
  });

  afterEach(() => {
    navigateSpy.mockRestore();
  });

  const openMenu = () => {
    fireEvent.click(screen.getByTitle('Open menu'));
  };

  it('renders the logout button when menu is open', async () => {
    await act(async () => { render(<UserNavBar />); });
    openMenu();
    expect(screen.getByText('Logout')).toBeInTheDocument();
  });

  it('calls logout() when logout button is clicked', async () => {
    (auth.logout as jest.Mock).mockResolvedValueOnce({ success: true });
    await act(async () => { render(<UserNavBar />); });
    openMenu();

    fireEvent.click(screen.getByText('Logout'));

    await waitFor(() => {
      expect(auth.logout).toHaveBeenCalledTimes(1);
    });
  });

  it('redirects to /login after logout (5.0.4 AT1)', async () => {
    (auth.logout as jest.Mock).mockResolvedValueOnce({ success: true });
    await act(async () => { render(<UserNavBar />); });
    openMenu();

    fireEvent.click(screen.getByText('Logout'));

    await waitFor(() => {
      expect(navigateSpy).toHaveBeenCalledWith('/login');
    });
  });

  it('navigates to /reports from the All reports menu item', async () => {
    const push = jest.fn();
    const { useRouter } = jest.requireMock('next/navigation');
    (useRouter as jest.Mock).mockReturnValue({ push });
    await act(async () => { render(<UserNavBar />); });
    openMenu();

    fireEvent.click(screen.getByText('All reports'));

    expect(push).toHaveBeenCalledWith('/reports');
  });

  it('opens my own profile from the My profile menu item (1.0.1 AT2)', async () => {
    const push = jest.fn();
    const { useRouter } = jest.requireMock('next/navigation');
    (useRouter as jest.Mock).mockReturnValue({ push });
    await act(async () => { render(<UserNavBar />); });
    openMenu();

    fireEvent.click(screen.getByText('My profile'));

    expect(push).toHaveBeenCalledWith('/profile');
  });

  it('keeps the user on the page and shows an error when sign-out fails (5.0.4 AT1)', async () => {
    (auth.logout as jest.Mock).mockResolvedValueOnce({ success: false, error: 'Network down' });
    await act(async () => { render(<UserNavBar />); });
    openMenu();

    fireEvent.click(screen.getByText('Logout'));

    expect(await screen.findByRole('alert')).toHaveTextContent(/sign-out failed/i);
    expect(navigateSpy).not.toHaveBeenCalled();
    expect(screen.getByText('Logout')).toBeInTheDocument();
  });

  it('closes the menu when logout is clicked', async () => {
    (auth.logout as jest.Mock).mockResolvedValueOnce({ success: true });
    await act(async () => { render(<UserNavBar />); });
    openMenu();

    fireEvent.click(screen.getByText('Logout'));

    await waitFor(() => {
      expect(screen.queryByText('Home')).not.toBeInTheDocument();
    });
  });
});